'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML, cfg=window.NEXORA_CONFIG, prefix='nexora_job_', sessionKey='nexora.jobs.session';
const safeRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let session=safeRead(sessionKey,null), language=localStorage.getItem('nexora.jobs.language')||'en', categories=[],jobs=[],myCandidate=null,myEmployer=null;
let routeEpoch=0,filterIds=new Set(), queryText='',cityText='',searchAll=false,authMode='login',dashboardTab='overview';
const t=(en,hi)=>language==='hi'?hi:en;
const isAdmin=()=>session?.user?.app_metadata?.job_portal_role==='admin';
const label=c=>language==='hi'?c.name_hi||c.name:c.name;
const catName=id=>{const c=categories.find(c=>c.id===id);return c?label(c):t('Archived profile','पुराना प्रोफ़ाइल')};
const money=v=>new Intl.NumberFormat('en-IN').format(v||0);
const toast=message=>{const n=$('#toast');n.textContent=message;n.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.style.display='none',4200)};
const saveSession=s=>{session=s;s?localStorage.setItem(sessionKey,JSON.stringify(s)):localStorage.removeItem(sessionKey);updateHeader()};
let refreshing;
async function refreshSession(){if(!session?.refresh_token)return; if(!refreshing)refreshing=(async()=>{const r=await fetch(cfg.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:cfg.supabaseKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});const d=await r.json();if(!r.ok){saveSession(null);throw Error(t('Session expired. Please log in again.','सत्र समाप्त हो गया। फिर लॉग इन करें।'))}saveSession(d)})().finally(()=>refreshing=null);return refreshing}
async function api(path,{method='GET',body,prefer}={}){if(session?.expires_at&&session.expires_at*1000<Date.now()+60000)await refreshSession();const h={apikey:cfg.supabaseKey,'Content-Type':'application/json'};if(session?.access_token)h.Authorization='Bearer '+session.access_token;if(prefer)h.Prefer=prefer;const r=await fetch(cfg.supabaseUrl+path,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body)});const text=await r.text();let data;try{data=text?JSON.parse(text):null}catch{throw Error('Server returned an unreadable response. Try again.')}if(!r.ok)throw Error(data?.msg||data?.message||data?.error_description||data?.error||'Request failed ('+r.status+')');return data}
const read=(table,query='')=>api('/rest/v1/'+prefix+table+'?'+query);
const write=async(table,body,id)=>{const rows=await api('/rest/v1/'+prefix+table+(id?'?id=eq.'+encodeURIComponent(id):''),{method:id?'PATCH':'POST',body,prefer:'return=representation'});if(!Array.isArray(rows)||!rows.length)throw Error('No record was saved. Check your account access and retry.');return rows;};
const upsert=(table,body)=>api('/rest/v1/'+prefix+table+'?on_conflict=user_id',{method:'POST',body,prefer:'resolution=merge-duplicates,return=representation'});
const draftKey=name=>'nexora.jobs.draft.'+(session?.user?.id||'guest')+'.'+name;

function restoreForm(form,values){if(!values)return;for(const [key,value]of Object.entries(values)){const input=form.elements.namedItem(key);if(input&&input instanceof HTMLElement){if(input.type==='checkbox')input.checked=!!value;else input.value=value??''}}}
function updateHeader(){$('#account').textContent=session?t('My account','मेरा खाता'):t('Log in','लॉग इन');$('#language').textContent=language==='hi'?'हिंदी / EN':'EN / हिंदी';document.documentElement.lang=language;}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function tags(ids,match=[]){return (ids||[]).map(id=>`<span class="tag ${match.includes(id)?'chip-highlight':''}">${e(catName(id))}</span>`).join('')}
function selector(name,ids=[],{title=t('Job Profile','जॉब प्रोफ़ाइल'),required=false,filter=false,history=[]}={}){ids=[...new Set(ids)].filter(id=>categories.some(c=>c.id===id&&(c.is_active||filter||history.includes(id))));const allowed=categories.filter(c=>c.is_active||ids.includes(c.id));return `<details class="category-selector" data-selector="${e(name)}" ${filter?'open':''} data-required="${required}"><summary><span>${e(title)}</span><small data-count>${ids.length} ${t('profiles selected','प्रोफ़ाइल चयनित')}</small><span class="chevron" aria-hidden="true">⌄</span></summary><div class="selector-tools"><input type="search" data-category-search placeholder="${t('Search profiles…','प्रोफ़ाइल खोजें…')}" aria-label="${t('Search job profiles','जॉब प्रोफ़ाइल खोजें')}"><button type="button" data-clear>${t('Clear Selection','चयन हटाएँ')}</button>${filter?'<button type="button" data-select-all>Select all</button>':''}</div><div class="category-options">${allowed.length?allowed.map(c=>`<label class="category-option" data-name="${e((c.name+' '+c.name_hi).toLowerCase())}"><input type="checkbox" data-category value="${e(c.id)}" ${ids.includes(c.id)?'checked':''} ${!c.is_active?'disabled':''}><span>${e(label(c))}${!c.is_active?` <span class="historical">(${t('inactive · saved','निष्क्रिय · सहेजा गया')})</span>`:''}</span></label>`).join(''):`<p class="form-help">${t('No categories available. Please try again later.','अभी कोई श्रेणी उपलब्ध नहीं है। बाद में प्रयास करें।')}</p>`}</div><div class="selector-note">${e(filter?t('Match by exact professional profiles.','सही प्रोफ़ाइल से मिलान करें।'):t('Choose your relevant skills. Saved inactive profiles are kept in your history.','संबंधित कौशल चुनें। पुराने निष्क्रिय प्रोफ़ाइल सुरक्षित रहेंगे।'))}</div></details>`}
const selected=sel=>[...new Set([...sel.querySelectorAll('[data-category]:checked')].map(x=>x.value))];
function formError(form,msg){const n=form.querySelector('[data-form-error]');n.textContent=msg;n.setAttribute('tabindex','-1');n.focus()}
async function submit(form,work){if(!form.reportValidity())return;const sel=form.querySelector('[data-selector][data-required="true"]');if(sel&&!selected(sel).length){sel.open=true;return formError(form,t('Select at least one job profile.','कम से कम एक जॉब प्रोफ़ाइल चुनें।'))}const b=form.querySelector('[type=submit]');b.disabled=true;try{await work()}catch(err){formError(form,err.message)}finally{if(b.isConnected)b.disabled=false}}
function field(name,title,type='text',value='',required=true){return `<label class="field">${e(title)}<input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='password'?'minlength="6" autocomplete="current-password"':''} ${type==='number'?'min="0"':''} ${name==='email'?'autocomplete="email"':''}></label>`}
function empty(title,message,action='jobs',button=t('Explore jobs','जॉब देखें')){return `<div class="empty"><div class="empty-icon">✦</div><h3>${e(title)}</h3><p>${e(message)}</p><button class="primary" data-action="${action}">${e(button)} ↗</button></div>`}
function jobCard(j){return `<article class="job-card"><div class="card-top"><span class="salon-icon">${e(j.salon_name.slice(0,1).toUpperCase())}</span><span class="status">${e(j.employment_type)}</span></div><div><h3>${e(j.title)}</h3><div class="company">${e(j.salon_name)}</div></div><div class="job-meta"><span>⌖ ${e(j.city)}</span><span>${new Date(j.created_at).toLocaleDateString(language==='hi'?'hi-IN':'en-IN',{month:'short',day:'numeric'})}</span></div><div>${tags(j.required_category_ids,myCandidate?.job_profile_category_ids||[])}</div><div class="card-bottom"><div class="salary">₹${money(j.salary_min)}–${money(j.salary_max)}<br><small>${t('per month','प्रति माह')}</small></div><button class="text-link" data-job="${e(j.id)}">${t('View job','जॉब देखें')} ↗</button></div></article>`}
function candidateCard(c){return `<article class="candidate-card"><div class="profile-person"><span class="avatar">${e(c.full_name.split(' ').map(s=>s[0]).join('').slice(0,2).toUpperCase())}</span><div><h3>${e(c.full_name)}</h3><p>⌖ ${e(c.city)} · ${c.experience_years} ${t('years experience','वर्ष अनुभव')}</p></div></div><div>${tags(c.job_profile_category_ids,[...filterIds])}</div><p class="form-help">${e(c.bio||t('Ready for the next opportunity.','नए अवसर के लिए तैयार।'))}</p><button class="secondary" data-invite="${e(c.user_id)}">${t('Invite to apply','आवेदन आमंत्रण')} ↗</button></article>`}
function downloadLink(className='primary',text=t('Download Android APK','Android APK डाउनलोड करें')){return `<a class="${className}" href="downloads/Nexora-Salon-Jobs.apk?v=1.0.5" download="Nexora-Salon-Jobs.apk">↓ ${text}</a>`}
function appBanner(){return `<div class="app-ribbon"><span><b>${t('Your next salon job, on your phone.','आपका अगला सैलून जॉब, आपके फ़ोन पर।')}</b> ${t('Nexora for Android','Android के लिए Nexora')}</span>${downloadLink('ribbon-download',t('Download APK','APK डाउनलोड करें'))}</div>`}
